# -*- coding: utf-8 -*-
# Счёт № AGR-С-2026-02 на 45% после акта утверждения ядра по договору AGR-2026-01 — из schet-agro-1.html
import os
ROOT=os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','..','..','..'))
s=open(os.path.join(ROOT,'app','schet-agro-1.html'),encoding='utf-8').read()
def r(a,b,n=1):
    global s
    assert s.count(a)==n,(s.count(a),a[:70]); s=s.replace(a,b)
r('<title>Счёт на предоплату № AGR-С-2026-01','<title>Счёт на оплату № AGR-С-2026-02')
r('СЧЁТ НА ОПЛАТУ № AGR-С-2026-01','СЧЁТ НА ОПЛАТУ № AGR-С-2026-02')
r('<div class="dt">от 19 октября 2026 г.</div><div class="st">предоплата 10% · старт работ</div>','<div class="dt">от 29 октября 2026 г.</div><div class="st">платёж 2 · 45% · ядро Системы</div>')
r('<h1>Счёт на предоплату</h1>','<h1>Счёт на оплату · этап 2</h1>')
i=s.index('<div class="note-top">');j=s.index('</div>',i)
s=s[:i]+'<div class="note-top"><b>Второй платёж — после утверждения ядра Системы.</b> Ядро (этап 2): Р2 — поля и агрооперации; Р3 — склады зерна, сеновал, отгрузка; Р4 — ГСМ и АЗС; Р5 — запчасти и техника; Р6 — животноводство и убойный цех; Р9.1 — роли и планшеты. Оплата — в течение 5 рабочих дней с даты акта утверждения ядра (п. 3.2 и Приложение № 2). Остаток 45% — после окончательной приёмки.'+s[j:]
r('<b>Предоплата 10% — старт работ.</b></td>\n        <td class="r">1</td><td class="r">242 500</td><td class="r">242 500</td>','<b>Этап 2 — ядро Системы, 45%.</b></td>\n        <td class="r">1</td><td class="r">1 091 250</td><td class="r">1 091 250</td>')
r('Сумма к оплате (предоплата 10%)</span><span class="v">242 500 ₸','Сумма к оплате (этап 2, 45%)</span><span class="v">1 091 250 ₸')
r('242 500 (двести сорок две тысячи пятьсот) тенге','1 091 250 (один миллион девяносто одна тысяча двести пятьдесят) тенге')
r('<div class="kv cur"><span>Платёж 1 · предоплата 10% — после подписания Договора<span class="tag">← текущий счёт</span></span><span>242 500 ₸</span></div>','<div class="kv"><span>Платёж 1 · предоплата 10% — после подписания Договора (счёт AGR-С-2026-01)</span><span>242 500 ₸</span></div>')
r('<div class="kv"><span>Платёж 2 · приёмка Ядра Системы (45%)</span><span>1 091 250 ₸</span></div>','<div class="kv cur"><span>Платёж 2 · приёмка Ядра Системы (45%)<span class="tag">← текущий счёт</span></span><span>1 091 250 ₸</span></div>')
r('242 500 ₸ в течение 5 рабочих дней с даты подписания Договора (п. 5.4).','1 091 250 ₸ в течение 5 рабочих дней с даты акта утверждения ядра Системы (Приложение № 2).')
r('Предоплата 10% по договору № AGR-2026-01 от 19.10.2026 за разработку программного обеспечения, счёт № AGR-С-2026-01. Без НДС','Оплата этапа 2 (ядро Системы, 45%) по договору № AGR-2026-01 от 19.10.2026 за разработку программного обеспечения, счёт № AGR-С-2026-02. Без НДС')
r('счёт AGR-С-2026-01 ·','счёт AGR-С-2026-02 ·')
assert 'AGR-С-2026-01' in s and '242 500 ₸</span></div>' in s
open(os.path.join(ROOT,'app','schet-agro-2.html'),'w',encoding='utf-8').write(s)
print('ok')
